UPDATE seckill_user_quota
SET reserved_quantity = reserved_quantity + #{quantity}, update_time = NOW()
WHERE activity_item_id = #{itemId}
  AND user_id = #{userId}
  AND reserved_quantity + #{quantity} <= #{limit}

UPDATE seckill_user_quota
SET reserved_quantity = GREATEST(0, reserved_quantity - #{quantity}), update_time = NOW()
WHERE activity_item_id = #{itemId} AND user_id = #{userId}
